<script setup lang="ts">const props=defineProps<{locale:'zh'|'en'}>();const input=ref('');const mode=ref<'encode'|'decode'>('encode');const result=computed(()=>{try{return mode.value==='encode'?encodeURIComponent(input.value):decodeURIComponent(input.value)}catch{return props.locale==='zh'?'错误：无效的 URL 编码':'Error: invalid URL encoding'}});const {copied,copy}=useCopy()</script><template><div class="tool-form"><div class="segmented"><button :class="{active:mode==='encode'}" @click="mode='encode'">{{locale==='zh'?'编码':'Encode'}}</button><button :class="{active:mode==='decode'}" @click="mode='decode'">{{locale==='zh'?'解码':'Decode'}}</button></div><label>{{locale==='zh'?'输入文本':'Input text'}}<textarea v-model="input" rows="5" :placeholder="locale==='zh'?'在这里输入文本':'Type text here'" /></label><div class="result-header"><span>{{locale==='zh'?'结果':'RESULT'}}</span><button type="button" @click="copy(result)">{{copied?(locale==='zh'?'已复制':'Copied'):(locale==='zh'?'复制':'Copy')}}</button></div><pre class="code-result">{{result}}</pre></div></template>